import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        long za = 0, zb = 0, sa = 0, sb = 0;
        for (int i = 0; i < n; i++) {
            long v = nextLong();
            sa += v;
            if (v == 0) za++;
        }
        for (int i = 0; i < m; i++) {
            long v = nextLong();
            sb += v;
            if (v == 0) zb++;
        }
        // Filling every 0 with 1 gives each row's minimum sum.
        sa += za;
        sb += zb;
        long target = Math.max(sa, sb);
        if ((za == 0 && sa != target) || (zb == 0 && sb != target)) System.out.println(-1);
        else System.out.println(target);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	za, zb, sa, sb := 0, 0, 0, 0
	for i := 0; i < n; i++ {
		v := nextInt()
		sa += v
		if v == 0 {
			za++
		}
	}
	for i := 0; i < m; i++ {
		v := nextInt()
		sb += v
		if v == 0 {
			zb++
		}
	}
	// Filling every 0 with 1 gives each row's minimum sum.
	sa += za
	sb += zb
	target := max(sa, sb)
	if (za == 0 && sa != target) || (zb == 0 && sb != target) {
		fmt.Println(-1)
	} else {
		fmt.Println(target)
	}
}
